const CACHE='tuka-v8';const SHELL=['./','./index.html','./style.css?v=8','./app.js?v=8','./transit.js?v=8','./live.js?v=8','./map-ui.js?v=8','./stop-network.js?v=8','./icon.svg','./manifest.webmanifest','./vendor/maplibre-gl.js','./vendor/maplibre-gl.css','./icon-192.png','./icon-512.png'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE&&k!=='tuka-schedule').map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request)))});
